-- The old Kanban user IDs were generated by the backend and are not the central identity UUIDs.
-- There are no production users to migrate. Clear user-owned application data so the first central
-- identity login can provision a fresh local profile without colliding with old unique email values.
-- CASCADE also truncates tables that reference user_entity (boards, memberships, cards, comments, etc.).

TRUNCATE TABLE user_entity CASCADE;

-- Provider-subject mappings now live only in the Webtools Identity Server.
DROP TABLE IF EXISTS user_provider;
